<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class UserRequest extends FormRequest { public function authorize(): bool { return $this->user() !== null; } public function rules(): array { if($this->isMethod('get')) return ['audience'=>['nullable',Rule::in(['pegawai','mahasiswa'])],'search'=>['nullable','string','max:255'],'per_page'=>['nullable','integer','min:5','max:100']]; $id=$this->route('user')?->id; return ['nama'=>['required','string','max:255'],'nim'=>['required','digits_between:5,20'],'email'=>['required','email',Rule::unique('users','email')->ignore($id)],'role_id'=>['required','integer','exists:roles,id'],'program_studi'=>['nullable','required_if:role_id,1','integer','in:1,2,3,4,5,6,7,8'],'password'=>[$this->isMethod('post')?'required':'nullable','string','min:6']]; } public function filters(): array { $d=$this->validated(); return ['audience'=>$d['audience']??'pegawai','search'=>$d['search']??null,'per_page'=>$d['per_page']??10]; } }
